import { describe, expect, it } from "vitest";
import { isValidEmail } from "../../src/validation/email";

// Hypothesis: the sign-up email validator excludes "+" from the local part.
// Asserts correct behaviour: fails while the bug exists, passes once fixed.
describe("patchsignal repro: plus-addressed email at sign-up", () => {
  it("accepts ade+test@gmail.com", () => {
    expect(isValidEmail("ade+test@gmail.com")).toBe(true);
  });

  it("still rejects an address with no domain", () => {
    expect(isValidEmail("ade+test@")).toBe(false);
  });
});

