import { describe, expect, it } from "vitest";
import { lineTotal, subtotal } from "../../src/cart/totals";

// Hypothesis: line totals are truncated (Math.floor) after a floating-point
// multiply, so 19.99 * 2 * 100 = 3997.9999... becomes 3997 cents.
describe("patchsignal repro: cart subtotal rounding", () => {
  it("prices 2 x $19.99 at $39.98", () => {
    expect(lineTotal({ sku: "TEE-BLK-M", unitPrice: 19.99, quantity: 2 })).toBe(39.98);
  });

  it("prices a cart of 2 x $19.99 + 1 x $5.00 at $44.98", () => {
    expect(
      subtotal([
        { sku: "TEE-BLK-M", unitPrice: 19.99, quantity: 2 },
        { sku: "SOCK-3PK", unitPrice: 5, quantity: 1 },
      ])
    ).toBe(44.98);
  });
});

