import { describe, expect, it } from "vitest";
import { pageSlice, totalPages } from "../../src/pagination";

// Hypothesis: totalPages adds a page whenever total is an exact multiple of
// pageSize, producing an empty last page.
describe("patchsignal repro: empty trailing catalog page", () => {
  it("needs exactly 2 pages for 40 products at 20 per page", () => {
    expect(totalPages(40, 20)).toBe(2);
  });

  it("never reports a page that has no products", () => {
    const products = Array.from({ length: 40 }, (_, i) => `sku-${i + 1}`);
    const last = totalPages(products.length, 20);
    expect(pageSlice(products, last, 20)).not.toHaveLength(0);
  });

  it("needs 3 pages for 41 products at 20 per page", () => {
    expect(totalPages(41, 20)).toBe(3);
  });
});

