import { describe, expect, it } from "vitest";
import { filterByDateRange } from "../../src/filters/dateRange";

// Hypothesis: the range filter treats the end date as exclusive and drops
// bookings on the last selected day.
describe("patchsignal repro: last day of the booking date range", () => {
  const bookings = [
    { id: "bk_101", startsAt: "2026-10-10T09:00:00Z" },
    { id: "bk_102", startsAt: "2026-10-15T14:30:00Z" },
    { id: "bk_103", startsAt: "2026-10-16T08:00:00Z" },
  ];

  it("includes a booking on the final day of the range", () => {
    const ids = filterByDateRange(bookings, "2026-10-10", "2026-10-15").map((b) => b.id);
    expect(ids).toContain("bk_102");
  });

  it("excludes the day after the range", () => {
    const ids = filterByDateRange(bookings, "2026-10-10", "2026-10-15").map((b) => b.id);
    expect(ids).not.toContain("bk_103");
  });
});

