import { describe, expect, it } from "vitest";
import { act, render, screen } from "@testing-library/react";
import { createElement } from "react";
import { SearchBox } from "../../src/search/SearchBox";

// Hypothesis: a slow response for the previous query resolves after the input
// is cleared and overwrites the empty result list.
describe("patchsignal repro: stale results after clearing search", () => {
  it("keeps the list empty when an earlier request resolves late", async () => {
    let resolve!: (rows: string[]) => void;
    const fetchResults = () => new Promise<string[]>((r) => (resolve = r));
    render(createElement(SearchBox, { fetchResults }));
    await act(async () => resolve(["react", "react-dom", "react-router"]));
    expect(screen.queryAllByRole("listitem")).toHaveLength(0);
  });
});

