import { describe, expect, it } from "vitest";
import { exportCsv } from "../../src/export/csv";

// Hypothesis: export never finishes when the row count is not a multiple of
// the batch size (10,500 rows, batches of 1,000).
describe("patchsignal repro: CSV export for a large workspace", () => {
  it("writes all 10,500 rows and returns", () => {
    const rows = Array.from({ length: 10_500 }, (_, i) => ({ id: i + 1, email: `user${i + 1}@example.com`, plan: "team" }));
    let bytes = 0;
    const written = exportCsv(rows, (chunk) => { bytes += chunk.length; });
    expect(written).toBe(10_500);
    expect(bytes).toBeGreaterThan(0);
  });
});
